<link rel="stylesheet" href="<?= e(\NxMultiTool\Registry::asset('calc.css')) ?>"><section class="nxmt-panel"><h2>電卓</h2><p>四則演算・小数・キーボード入力に対応します。</p><div class="nxmt-calc" data-nxmt-calc tabindex="0"><div class="nxmt-calc-display" data-nxmt-calc-display aria-live="polite">0</div><div class="nxmt-calc-extra"></div><div class="nxmt-calc-keys"><?php foreach (['AC','÷','×','-','7','8','9','+','4','5','6','=','1','2','3','0','.'] as $key): ?><button type="button" data-key="<?= e($key) ?>" <?= $key === 'AC' ? 'data-act="ac"' : ($key === '=' ? 'data-act="eq"' : (in_array($key, ['+','-','×','÷']) ? 'data-op="' . e($key) . '"' : 'data-num="' . e($key) . '"')) ?> class="<?= $key === '=' ? 'eq' : ($key === '0' ? 'zero' : '') ?>"><?= e($key) ?></button><?php endforeach; ?></div></div></section><script src="<?= e(\NxMultiTool\Registry::asset('calc.js')) ?>" defer></script>
